arguments.new_str:
namespace Payments;

public sealed class PaymentGateway
{
    private readonly IPaymentProvider _provider;

    public PaymentGateway(IPaymentProvider provider)
    {
        _provider = provider ?? throw new ArgumentNullException(nameof(provider));
    }

    public async Task<ChargeResult> ChargeAsync(string cardToken, decimal amount)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(cardToken);

        if (amount <= 0)
            throw new ArgumentOutOfRangeException(nameof(amount), "Amount must be positive.");

        if (amount > 999_999.99m)
            throw new ArgumentOutOfRangeException(nameof(amount), "Amount exceeds maximum.");

        return await _provider.ChargeAsync(cardToken, amount);
    }

    public async Task<RefundResult> RefundAsync(string chargeId)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(chargeId);

        return await _provider.RefundAsync(chargeId);
    }

    public Task<WebhookResult> ProcessWebhookAsync(WebhookEvent webhookEvent)
    {
        ArgumentNullException.ThrowIfNull(webhookEvent);

        return webhookEvent.Type switch
        {
            "charge.succeeded" => Task.FromResult(new WebhookResult(Processed: true)),
            "charge.failed" => Task.FromResult(new WebhookResult(Processed: true)),
            "charge.refunded" => Task.FromResult(new WebhookResult(Processed: true)),
            _ => Task.FromResult(new WebhookResult(Processed: false, Error: $"Unknown event type: {webhookEvent.Type}")),
        };
    }
}

public record ChargeResult(string ChargeId, bool Success);
public record RefundResult(string RefundId, bool Success);

