using Payments;

namespace PaymentGateway.Tests;

[TestClass]
public sealed class PaymentGatewayTests
{
    private readonly FakePaymentProvider _provider;
    private readonly Payments.PaymentGateway _gateway;

    public PaymentGatewayTests()
    {
        _provider = new FakePaymentProvider();
        _gateway = new Payments.PaymentGateway(_provider);
    }

    #region Constructor

    [TestMethod]
    public void Ctor_NullProvider_ThrowsArgumentNullException()
    {
        var ex = Assert.ThrowsExactly<ArgumentNullException>(
            () => new Payments.PaymentGateway(null!));
        Assert.AreEqual("provider", ex.ParamName);
    }

    #endregion

    #region ChargeAsync — happy path

    [TestMethod]
    public async Task ChargeAsync_ValidInput_ReturnsChargeResult()
    {
        _provider.ChargeResultToReturn = new ChargeResult("ch_123", Success: true);

        var result = await _gateway.ChargeAsync("tok_visa", 49.99m);

        Assert.IsTrue(result.Success);
        Assert.AreEqual("ch_123", result.ChargeId);
    }

    [TestMethod]
    public async Task ChargeAsync_ValidInput_ForwardsTokenAndAmount()
    {
        _provider.ChargeResultToReturn = new ChargeResult("ch_1", true);

        await _gateway.ChargeAsync("tok_mc", 100m);

        Assert.AreEqual("tok_mc", _provider.LastCardToken);
        Assert.AreEqual(100m, _provider.LastAmount);
    }

    [TestMethod]
    public async Task ChargeAsync_ProviderReturnsFailed_ReturnsFalseSuccess()
    {
        _provider.ChargeResultToReturn = new ChargeResult("ch_fail", Success: false);

        var result = await _gateway.ChargeAsync("tok_visa", 10m);

        Assert.IsFalse(result.Success);
    }

    [TestMethod]
    [DataRow(0.01, DisplayName = "Minimum charge")]
    [DataRow(999999.99, DisplayName = "Maximum charge")]
    [DataRow(500.00, DisplayName = "Mid-range charge")]
    public async Task ChargeAsync_BoundaryAmounts_Succeeds(double amount)
    {
        _provider.ChargeResultToReturn = new ChargeResult("ch_ok", true);

        var result = await _gateway.ChargeAsync("tok_visa", (decimal)amount);

        Assert.IsTrue(result.Success);
    }

    #endregion

    #region ChargeAsync — validation

    [TestMethod]
    public async Task ChargeAsync_NullToken_ThrowsArgumentException()
    {
        await Assert.ThrowsExactlyAsync<ArgumentNullException>(
            async () => await _gateway.ChargeAsync(null!, 10m));
    }

    [TestMethod]
    [DataRow("")]
    [DataRow("   ")]
    public async Task ChargeAsync_EmptyOrWhitespaceToken_ThrowsArgumentException(string token)
    {
        await Assert.ThrowsExactlyAsync<ArgumentException>(
            async () => await _gateway.ChargeAsync(token, 10m));
    }

    [TestMethod]
    [DataRow(0)]
    [DataRow(-1)]
    [DataRow(-0.01)]
    public async Task ChargeAsync_NonPositiveAmount_ThrowsArgumentOutOfRangeException(double amount)
    {
        var ex = await Assert.ThrowsExactlyAsync<ArgumentOutOfRangeException>(
            async () => await _gateway.ChargeAsync("tok_visa", (decimal)amount));
        Assert.AreEqual("amount", ex.ParamName);
    }

    [TestMethod]
    public async Task ChargeAsync_AmountExceedsMax_ThrowsArgumentOutOfRangeException()
    {
        var ex = await Assert.ThrowsExactlyAsync<ArgumentOutOfRangeException>(
            async () => await _gateway.ChargeAsync("tok_visa", 1_000_000m));
        Assert.AreEqual("amount", ex.ParamName);
    }

    #endregion

    #region ChargeAsync — provider errors

    [TestMethod]
    public async Task ChargeAsync_ProviderThrows_ExceptionPropagates()
    {
        _provider.ExceptionToThrow = new InvalidOperationException("Gateway timeout");

        await Assert.ThrowsExactlyAsync<InvalidOperationException>(
            async () => await _gateway.ChargeAsync("tok_visa", 25m));
    }

    #endregion

    #region RefundAsync — happy path

    [TestMethod]
    public async Task RefundAsync_ValidChargeId_ReturnsRefundResult()
    {
        _provider.RefundResultToReturn = new RefundResult("re_456", Success: true);

        var result = await _gateway.RefundAsync("ch_123");

        Assert.IsTrue(result.Success);
        Assert.AreEqual("re_456", result.RefundId);
    }

    [TestMethod]
    public async Task RefundAsync_ValidChargeId_ForwardsChargeId()
    {
        _provider.RefundResultToReturn = new RefundResult("re_1", true);

        await _gateway.RefundAsync("ch_abc");

        Assert.AreEqual("ch_abc", _provider.LastChargeId);
    }

    [TestMethod]
    public async Task RefundAsync_ProviderReturnsFailed_ReturnsFalseSuccess()
    {
        _provider.RefundResultToReturn = new RefundResult("re_fail", Success: false);

        var result = await _gateway.RefundAsync("ch_123");

        Assert.IsFalse(result.Success);
    }

    #endregion

    #region RefundAsync — validation

    [TestMethod]
    public async Task RefundAsync_NullChargeId_ThrowsArgumentException()
    {
        await Assert.ThrowsExactlyAsync<ArgumentNullException>(
            async () => await _gateway.RefundAsync(null!));
    }

    [TestMethod]
    [DataRow("")]
    [DataRow("   ")]
    public async Task RefundAsync_EmptyOrWhitespaceChargeId_ThrowsArgumentException(string chargeId)
    {
        await Assert.ThrowsExactlyAsync<ArgumentException>(
            async () => await _gateway.RefundAsync(chargeId));
    }

    #endregion

    #region RefundAsync — provider errors

    [TestMethod]
    public async Task RefundAsync_ProviderThrows_ExceptionPropagates()
    {
        _provider.ExceptionToThrow = new InvalidOperationException("Network error");

        await Assert.ThrowsExactlyAsync<InvalidOperationException>(
            async () => await _gateway.RefundAsync("ch_123"));
    }

    #endregion

    #region ProcessWebhookAsync — known event types

    [TestMethod]
    [DataRow("charge.succeeded", DisplayName = "Charge succeeded")]
    [DataRow("charge.failed", DisplayName = "Charge failed")]
    [DataRow("charge.refunded", DisplayName = "Charge refunded")]
    public async Task ProcessWebhookAsync_KnownEventType_ReturnsProcessedTrue(string eventType)
    {
        var webhook = new WebhookEvent(eventType, "ch_123");

        var result = await _gateway.ProcessWebhookAsync(webhook);

        Assert.IsTrue(result.Processed);
        Assert.IsNull(result.Error);
    }

    #endregion

    #region ProcessWebhookAsync — unknown event types

    [TestMethod]
    public async Task ProcessWebhookAsync_UnknownEventType_ReturnsProcessedFalse()
    {
        var webhook = new WebhookEvent("invoice.paid", "ch_123");

        var result = await _gateway.ProcessWebhookAsync(webhook);

        Assert.IsFalse(result.Processed);
        Assert.IsNotNull(result.Error);
        Assert.Contains("invoice.paid", result.Error);
    }

    #endregion

    #region ProcessWebhookAsync — validation

    [TestMethod]
    public async Task ProcessWebhookAsync_NullEvent_ThrowsArgumentNullException()
    {
        await Assert.ThrowsExactlyAsync<ArgumentNullException>(
            async () => await _gateway.ProcessWebhookAsync(null!));
    }

    #endregion
}

